  "common.js": "var table;\nvar common = {\n  fullModel_win: \"https://www.ljxfw.gov.cn/gateway2/portal-ljxfw\", // 飘窗文字接口\n  fullModel: \"https://www.ljxfw.gov.cn/gateway2/portal-ljxfw/ljxfw\", //线上\n apiUrl: \"https://www.ljxfw.gov.cn/gateway2/portal-ljxfw/ljxfw\", //线上\nwebUrl: \"https://www.ljxfw.gov.cn/ljxfwWeb/\", //线上项目地址前缀\n  imgUrl: \"\", //线上图片路径\n  videoUrl: \"\", //视频公共前缀-暂时使用的文件前缀\n  tempUrl: \"\", //图片长前缀路径\n  tabUrl: \"\", //tab栏图标前缀路径-@Kira\n  clickUrl: \"https://www.ljxfw.gov.cn/gateway\", //点击量前缀生产\n  testImgVideo: \"\", //我和我的祖国生产\n  tempUrlTest: \"\", //中共党员教育平台系列、飘窗、党教视界\n  partyLife: \"https://www.ljxfw.gov.cn/hljDdsh/detail.html?infoId=\", // 文章的outside_id\n\n  ajaxUtil: function (url, params, callBack, method, sync, filter) {\n    $.ajax({\n      type: method == undefined ? \"get\" : method,\n      url: url,\n      async: sync == undefined ? true : sync,\n      data: params,\n      dataTpye: \"json\",\n      success: function (result) {\n        if (result.code == 1003) {\n          common.tokenOut(\"此帐号已在其他地方登录，您已被迫下线\");\n        } else {\n          callBack(result.obj);\n        }\n      },\n      error: function (data) {\n        if (data.status == 401) {\n          //判断token失效后，接口返回报错信息status值为401\n          if (common.tokenFlag) {\n            common.tokenFlag = false;\n            common.tokenOut(\"登录失效，请重新登录！\");\n          }\n        }\n      },\n      dataFilter: filter == undefined ? null : filter,\n    });\n  },\n\n  tokenOut: function (msg) {\n    if (window.top) {\n      parent.layer.confirm(\n        msg,\n        {\n          btn: [\"确定\"],\n          cancel: function () {\n            common.tokenFlag = true;\n            parent.common.logout(); //退出登录\n          }, //按钮\n        },\n        function () {\n          common.tokenFlag = true;\n          parent.common.logout(); //退出登录\n        }\n      );\n    } else {\n      layer.confirm(\n        msg,\n        {\n          btn: [\"确定\"],\n          cancel: function () {\n            common.tokenFlag = true;\n            common.logout(); //退出登录\n          }, //按钮\n        },\n        function () {\n          common.tokenFlag = true;\n          common.logout(); //退出登录\n        }\n      );\n    }\n  },\n\n  /**\n\t * \n\t * @param {pageId:分页div的id,curr:当前页,url:请求地址,pageSize:每页显示条数,id:显示数据的div的id,packageData:动态页面方法} args\n\t页面定义方式\n\tvar args = {\n\t\turl: \"partyClassAPI/get/partyClassList\",\n\t\tmethod: \"post\",\n\t\tparams: {\n\t\t\taccess_token: common.getAccessToken,\n\t\t\tpageNo: 1,\n\t\t\tpageSize: 10,\n\t\t\tisChild: isChild,\n\t\t},\n\t\tpageId: \"layerPage\",\n\t\tpackageData: findPageCallBack,\n\t\tfilter:common.ajaxDataFilter\n\t}\n\t调用方式\n\tcommon.pagingnew(args);\n\t* */\n  paging: function (args) {\n    common.ajaxUtil(\n      args.url,\n      args.params,\n      function (result) {\n        layui.use([\"laypage\", \"layer\"], function () {\n          var laypage = layui.laypage;\n          //完整功能\n          laypage.render({\n            elem: args.pageId, //id\n            count: result.totalCount, //数据条数\n            limit: args.params.pageSize,\n            curr: args.params.pageNo,\n            first: \"首页\",\n            last: \"尾页\",\n            layout: [\"prev\", \"page\", \"next\", \"count\"], //显示上一页，下一页，页码，总页数\n            jump: function (obj, first) {\n              if (!first) {\n                localStorage.setItem(\"currPage\", obj.curr || 1);\n                args.params.pageNo = obj.curr;\n                if (args.params.type == \"notice\" && args.params.pageNo > 1) {\n                  delete args.params.topSize;\n                } else {\n                  args.params.topSize = 1;\n                }\n                common.paging(args);\n              }\n            },\n          });\n        });\n        args.packageData(result);\n      },\n      args.method == undefined ? \"get\" : args.method,\n      args.sync == undefined ? \"get\" : args.method,\n      args.filter == null ? null : args.filter\n    );\n  },\n  pagingnew: function (args) {\n    common.ajaxUtil(\n      args.url,\n      args.params,\n      function (result) {\n        layui.use([\"laypage\", \"layer\"], function () {\n          var laypage = layui.laypage;\n          //完整功能\n          laypage.render({\n            elem: args.pageId, //id\n            count: result.totalCount, //数据条数\n            limit: args.params.pageSize,\n            curr: args.params.pageNo,\n            first: \"首页\",\n            last: \"尾页\",\n            //\t\t\t\t\t    layout: ['prev','page','next','count', 'skip'],//显示上一页，下一页，页码，总页数\n            layout: [\"prev\", \"page\", \"next\", \"count\"], //显示上一页，下一页，页码，总页数\n            jump: function (obj, first) {\n              if (!first) {\n                localStorage.setItem(\"currPage\", obj.curr || 1);\n                args.params.pageNo = obj.curr;\n                common.pagingnew(args);\n              }\n            },\n          });\n        });\n\n        args.packageData(result);\n      },\n      args.method == undefined ? \"get\" : args.method\n    );\n  },\n  pagingNew: function (args) {\n    common.ajaxUtil(\n      args.url,\n      args.params,\n      function (result) {\n        if (0 != result.length) {\n          layui.use([\"laypage\", \"layer\"], function () {\n            var laypage = layui.laypage;\n            //完整功能\n            laypage.render({\n              elem: args.pageId, //id\n              count: result[0].informationList.totalCount, //数据条数\n              limit: args.params.pageSize,\n              curr: args.params.pageNo,\n              first: \"首页\",\n              last: \"尾页\",\n              layout: [\"prev\", \"page\", \"next\", \"count\"], //显示上一页，下一页，页码，总页数\n              jump: function (obj, first) {\n                if (!first) {\n                  localStorage.setItem(\"currPage\", obj.curr || 1);\n                  args.params.pageNo = obj.curr;\n                  common.pagingNew(args);\n                }\n              },\n            });\n          });\n          args.packageData(result);\n        }\n      },\n      args.method == undefined ? \"get\" : args.method,\n      args.sync == undefined ? \"get\" : args.method,\n      args.filter == null ? null : args.filter\n    );\n  },\n\n  /*\n\t例子： 获取详情页面带回来的pageNo或id等页面需要参数，用路径拼接，getUrlParams方法进行接收\n\t var pageNo = common.getUrlParams(\"pageNo\");\n\t var id = common.getUrlParams(\"id\");\n\t * */\n  getUrlParams: function (para) {\n    var paraArr = location.search.substring(1).split(\"&\");\n    for (var i = 0; i < paraArr.length; i++) {\n      if (para == paraArr[i].split(\"=\")[0]) {\n        return paraArr[i].split(\"=\")[1];\n      }\n    }\n    return \"\";\n  },\n  href: function (url) {\n    //详情\n    location.href = url;\n  },\n  hrefMyInfo_: function (url, infoId) {\n    //列表跳详情\n    location.href = url + \"?infoId=\" + infoId;\n  },\n  imageError: function (dom, defaultImagePath) {\n    $(dom).attr(\"src\", defaultImagePath);\n  },\n  uuid: function () {\n    var s = [];\n    var hexDigits = \"0123456789abcdef\";\n    for (var i = 0; i < 36; i++) {\n      s[i] = hexDigits.substr(Math.floor(Math.random() * 0x10), 1);\n    }\n    s[14] = \"4\";\n    // bits 12-15 of the time_hi_and_version field to 0010\n    s[19] = hexDigits.substr((s[19] & 0x3) | 0x8, 1);\n    // bits 6-7 of the clock_seq_hi_and_reserved to 01\n    s[8] = s[13] = s[18] = s[23] = \"-\";\n    var uuid = s.join(\"\");\n    return uuid;\n  },\n  mainHeight: function () {\n    var htmlHei = $(\".html\").innerHeight();\n    var bodyHei = $(\".body\").innerHeight();\n    var headerHei = $(\".header\").innerHeight();\n    var footerHei = $(\".footer\").innerHeight();\n    if (bodyHei + 1 < htmlHei) {\n      var mainHeight = htmlHei - headerHei - footerHei - 80 + \"px\";\n      $(\".mainHeight\").css(\"height\", mainHeight);\n    } else {\n      $(\".mainHeight\").attr(\"style\", \"margin-top: 80px;\");\n    }\n  },\n  filterHTMLTag: function (msg) {\n    var msg = msg.replace(/<\\/?[^>]*>/g, \"\"); //去除HTML Tag\n    msg = msg.replace(/[|]*\\n/, \"\"); //去除行尾空格\n    msg = msg.replace(/&npsp;/gi, \"\"); //去掉npsp\n    return msg;\n  },\n  ajaxDataFilter: function (data, type) {\n    //获得数据是对数据进行编译（解决id是long型数据缺失问题）\n    data = data.replace(/id\\\":(\\d+)/g, 'id\":\"$1\"');\n    return data;\n  },\n  //处理时间戳\n  createTime: function (data, format) {\n    if (data != null) {\n      var date = new Date(data);\n      var map = {\n        M: date.getMonth() + 1, //月份\n        d: date.getDate(), //日\n        h: date.getHours(), //小时\n        m: date.getMinutes(), //分\n        s: date.getSeconds(), //秒\n        q: Math.floor((date.getMonth() + 3) / 3), //季度\n        S: date.getMilliseconds(), //毫秒\n      };\n      format = format.replace(/([yMdhmsqS])+/g, function (all, t) {\n        var v = map[t];\n        if (v !== undefined) {\n          if (all.length > 1) {\n            v = \"0\" + v;\n            v = v.substr(v.length - 2);\n          }\n          return v;\n        } else if (t === \"y\") {\n          return (date.getFullYear() + \"\").substr(4 - all.length);\n        }\n        return all;\n      });\n      return format;\n    } else {\n      return \"暂无数据\";\n    }\n  },\n\n  getLocalTime: function (param) {\n    return new Date(parseInt(param)).format(\"yyyy-MM-dd\");\n  },\n};\n\n/* 支部建设:branchInfo;教育:education;门户:portal;党建地图:partyMap;APP:app;专家系统：export;平台:platform;\n * 专题:不忘初心牢记使命:cxsm;\n * 学习宣传省第十二次党代会精神:Ddhjs\n * 党性教育红色展馆:Hszg\n * 党的生活:Ddsh\n * 党员电教:Dydj\n * 解放思想推动高质量发展大讨论:Jfsxdtl\n * 解放思想推动革新发展大讨论:Jfsxgfz\n * 学习贯彻党的十九大精神:Shijiu\n * 黑龙江省微信矩阵:Wxjz\n * 市委书记进校园宣讲专栏:Xjzt\n * 学习贯彻习近平新时代中国特色社会主义思想:Xxgc\n *\n */\nvar _maq = _maq || [];\n_maq.push([\"_setAccount\", \"portal\"]); // 这里是标识字段名-account\n(function () {\n  var ma = document.createElement(\"script\");\n  ma.type = \"text/javascript\";\n  //ma.async = true;///同步异步\n  ma.src = \"https://www.ljxfw.gov.cn/publicjs/cookieHm.js\"; //这个是请求用户行为分析的js地址\n  var s = document.getElementsByTagName(\"script\")[1];\n  s.parentNode.insertBefore(ma, s);\n})();\n\n//百度统计\nvar _hmt = _hmt || [];\n(function () {\n  var hm = document.createElement(\"script\");\n\n  $.ajax({\n    type: \"get\",\n    url: \"https://www.ljxfw.gov.cn/json/btCode.json\",\n    async: false,\n    dataTpye: \"text\",\n    success: function (res) {\n      let jsonKey =\n        location.pathname.split(\"/\")[1] == \"\"\n          ? \"base\"\n          : location.pathname.split(\"/\")[1];\n      hm.src = \"https://hm.baidu.com/hm.js?\" + res.obj[jsonKey];\n      var s = document.getElementsByTagName(\"script\")[document.getElementsByTagName(\"script\").length-1];\n      s.parentNode.insertBefore(hm, s);\n    },\n    error: function (err) {\n//    console.info(err);\n    },\n  });\n})();\n",
  "commonParams.js": "var commonParams = {\n\t\n\t//公共基础接口参数\n\tsiteId: 0,\n\tpageSize_four:4,\n\tpageSize_five: 5,\n\tpageSize_seven: 7,\n\tpageSize_ten: 10,\n\tpageSize_one: 1,\n\tisShow: '1',//接口文档4.7\n\t\n\t//栏目nodeId\n\timportNew: '278B180ED70ECF61552B2DA8E29C19E0',// 要闻聚焦\n\thighRise: '7D741CB7F6FF2D413EB875B6B5A9BCC3',// 高层声音（习大大）FBAB14AE07362E34E01B22D8EC367273           \n\thighRisey:'FBAB14AE07362E34E01B22D8EC367273',//杨鹏用\n\timportantNews: 'A1C4908A08A8E251863811245BE48E55',//龙江要闻（张庆伟）D4EEAEA88C1ABF9E95DD0801A2491346\n\timportantNewsy:'D4EEAEA88C1ABF9E95DD0801A2491346',//杨鹏用\n\tleaderActivities: '47F355887F3037B0124ACC50F07A8AD9',//  部领导活动（部长）\n\tleaderActiveTab: 'DC4C09B30AB143733D8F3641D56E91D4',//  部领导活动（栏目）\n\timportantNewsTab: 'D4EEAEA88C1ABF9E95DD0801A2491346',//龙江要闻（栏目）\n    dlhTab: 'C9CE8BA7AD94582A1FB4EEC6C22ED1CD',//党代会（栏目）\n\tmyHome:'27D02799DA49769826BE9C555CE6340D',//我和我的祖国\n\tnotice: 'F1A6A92D3601F984F2006B5D50233952',//通知公告\n\tcadresPublic: 'F17F051EDE368B09911E73A6700C76C3',//干部公示\n\tyjsgkPublic:'C6500FB7B571E1679C488E1E46E34A5E,64C86FD01B71A1A8F123894D3E62601C',//预决算公开\n\tpartyFreely: '05E1162ADB72ADAFF892CFE81459A727',//党建纵横\n\ttalentWorld: '99EB4E5AAF0A416E7E035576891A5FEC',//人才天地\n\tservantManager: '879FA0DC3DA7674E1918808D57EC3239',//公务员管理\n\tcadresWindow: '8C902AD4DE93D253347FBA3BE2EF035C',// 干部之窗\n\tgardenPlot: 'C2A092C1841E7376E8163ED4C0480106',//组工园地 改名叫组工动态\n\tfieldVision: '270FF5D280F6BE040E1DCD7D5CD3E8EE',//远教视界\n\tfarEduTrends: '3E33B82C844A996D9CE1DED9B11D152E',// 远教动态\n\ttrainArrange: '0675854BE41CED03DD125011B6A7E2C5',// 培训安排\n\tlaw\t: '373458F829104DBEB73AB58DD5228D02',//政策法规\n\tstone: '2DF5D8E6D497B564960B05DC4DB8E0A5',// 他山之石\n\t\n\tselfBuild: 'B4199AB3D4FF7D5FC919ABC7F2F605CE',//自身建设 \n\tselfBuildSub: '8446EBA4B902FFCD3057AE3821681D2C,48D18D9A1554A52B408665ADDD32FC8A',//省、市自身建设\n\torganizationGarden: '599FB2D468E22EABB73180FB74653478,E8A4EAD2DEE8CFD97D5057748286DA43,8446EBA4B902FFCD3057AE3821681D2C,48D18D9A1554A52B40866