}

.hero-image {
  position: relative;
}

.hero-image img {
  width: 100%;
  border-radius: 8px;
  height: 320px;
  object-fit: cover;
}

.caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  color: #fff;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.75));
  padding: 26px 12px 10px;
  border-radius: 0 0 8px 8px;
}

.tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.tab-button {
  border: none;
  background: #f0f2f7;
  color: #555;
  border-radius: 20px;
  padding: 6px 12px;
  cursor: pointer;
}

.tab-button.active {
  background: #b40000;
  color: #fff;
}

.hero-list ul,
.panel ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.hero-list li,
.panel li {
  padding: 8px 0;
  border-bottom: 1px dashed #ddd;
}

.hero-list li:last-child,
.panel li:last-child {
  border-bottom: none;
}

.date {
  font-size: 12px;
  margin-right: 8px;
  color: #888;
}

.hero-list a {
  text-decoration: none;
  color: #333;
}

.section-grid {
  margin-top: 16px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.panel {
  padding: 14px;
}

.panel-title {
  font-size: 20px;
  font-weight: bold;
  color: #9c0000;
  border-left: 5px solid #b40000;
  padding-left: 10px;
  margin-bottom: 10px;
}

.site-footer {
  text-align: center;
  padding: 22px 16px 30px;
  color: #666;
}

@media (max-width: 900px) {
  .hero-news {
    grid-template-columns: 1fr;
  }

  .hero-image img {
    height: 220px;
  }

  .section-grid {
    grid-template-columns: 1fr;
  }
}
</style>

